from math import isqrt


def sum_div(n):
    """Return the sum of positive divisors of n, excluding n itself."""
    if n <= 1:
        return 0

    total = 1
    for divisor in range(2, isqrt(n) + 1):
        if n % divisor == 0:
            total += divisor
            paired_divisor = n // divisor
            if paired_divisor != divisor:
                total += paired_divisor
    return total
